package cn.zhigeng.app;

import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

/** Independent native node and AI membership directories using the user's latest selected lists. */
public class DirectoryActivity extends Activity {
    private final int BG=0xfff7f5ef,INK=0xff203b32,MUTED=0xff78837a,GREEN=0xff244e40,PALE=0xffe9eee7;
    private final ExecutorService jobs=Executors.newSingleThreadExecutor();
    private SharedPreferences prefs;private JSONObject data;private String mode,filter="all",query="",brand="all",delivery="all";
    private LinearLayout body,cards,filters;private TextView status,count;private Button refresh;private boolean refreshing=false;
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private LinearLayout col(){LinearLayout n=new LinearLayout(this);n.setOrientation(1);return n;}
    private LinearLayout row(){LinearLayout n=new LinearLayout(this);n.setGravity(Gravity.CENTER_VERTICAL);return n;}
    private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(3),1.1f);return t;}
    private void add(LinearLayout parent,View child,int margin){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(margin);parent.addView(child,lp);}
    private Button button(String title,boolean strong){Button b=new Button(this);b.setText(title);b.setTextSize(12);b.setAllCaps(false);b.setStateListAnimator(null);b.setTextColor(strong?0xffffffff:GREEN);b.setMinHeight(dp(44));b.setMinimumHeight(dp(44));b.setPadding(dp(12),dp(8),dp(12),dp(8));b.setBackground(shape(strong?GREEN:PALE,20));return b;}
    private Set<String> favorites(){return new HashSet<>(prefs.getStringSet(mode+":favorites",Collections.emptySet()));}
    private String asset(){return mode.equals("nodes")?"node-sites.json":"ai-memberships.json";}
    private String read(InputStream in)throws Exception {ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] chunk=new byte[8192];int n;while((n=in.read(chunk))!=-1){if(b.size()+n>100000)throw new IOException("目录数据过大");b.write(chunk,0,n);}return b.toString("UTF-8");}
    @Override public void onCreate(Bundle state){super.onCreate(state);mode="nodes".equals(getIntent().getStringExtra("mode"))?"nodes":"memberships";prefs=getSharedPreferences("service-directories",MODE_PRIVATE);
        if(state!=null){filter=state.getString("filter","all");query=state.getString("query","");brand=state.getString("brand","all");delivery=state.getString("delivery","all");}
        try{String cached=prefs.getString(mode+":data","");try{data=ServiceDirectory.validate(mode,cached);}catch(Exception e){try(InputStream in=getAssets().open(asset())){data=ServiceDirectory.validate(mode,read(in));}}}catch(Exception e){new AlertDialog.Builder(this).setMessage("目录暂时无法读取").setPositiveButton("返回",(d,w)->finish()).show();return;}
        getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
        LinearLayout root=col();root.setBackgroundColor(BG);LinearLayout bar=row();bar.setPadding(dp(16),dp(8),dp(16),dp(8));Button back=button("‹ 返回",false);back.setOnClickListener(v->finish());bar.addView(back);TextView title=text(mode.equals("nodes")?"节点导航 5＋5":"AI 会员",18,INK);title.setPadding(dp(16),0,0,0);title.setTypeface(null,Typeface.BOLD);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));refresh=button("刷新",false);refresh.setContentDescription("刷新最新网站目录");refresh.setOnClickListener(v->refresh());bar.addView(refresh);root.addView(bar);
        ScrollView scroll=new ScrollView(this);body=col();body.setPadding(dp(20),dp(6),dp(20),dp(30));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
        LinearLayout hero=col();hero.setPadding(dp(22),dp(20),dp(22),dp(22));hero.setBackground(shape(GREEN,26));add(hero,text(mode.equals("nodes")?"PROXY / SUBSCRIPTION":"MEMBERSHIPS / COMPARE",10,PALE),0);TextView slogan=text(mode.equals("nodes")?"常用节点，\n分组收好。":"订阅之前，\n先看清楚。",27,BG);slogan.setTypeface(null,Typeface.BOLD);add(hero,slogan,10);add(hero,text(mode.equals("nodes")?"代理 IP 5 家 · 机场 5 家 · 额外控制台":"截图指定 5 个主推荐 · 2 个备选",12,PALE),10);add(body,hero,8);
        EditText search=new EditText(this);search.setSingleLine();search.setTextSize(14);search.setTextColor(INK);search.setHintTextColor(MUTED);search.setHint("搜索名称、网址或服务…");search.setContentDescription("搜索网站目录");search.setBackground(shape(0xffffffff,15));search.setPadding(dp(14),dp(10),dp(14),dp(10));search.setText(query);add(body,search,18);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();renderCards();}public void afterTextChanged(Editable e){}});
        if(mode.equals("memberships"))membershipFilters();HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);filters=row();hs.addView(filters);add(body,hs,12);count=text("",11,MUTED);add(body,count,14);status=text("名单日期："+data.optString("updatedAt")+" · 收藏只存在本机",11,MUTED);add(body,status,4);cards=col();add(body,cards,0);renderCards();
        add(body,text(mode.equals("nodes")?"支付、IP 信誉、AI 可用性和长期稳定性并未实测；第5家代理 IPRoyal 仍为已标注候选。详情保留来源和核实程度。":data.optString("disclaimer"),11,MUTED),20);
    }
    private Spinner spinner(String[] labels,int selected){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));s.setSelection(selected);return s;}
    private void membershipFilters(){LinearLayout options=col();String[] brands={"all","ChatGPT","Claude","Gemini","Grok","Cursor","其他"},types={"all","own","shared","redeem","account","mirror","compare"};Spinner b=spinner(new String[]{"全部 AI 产品","ChatGPT","Claude","Gemini","Grok","Cursor","其他"},Math.max(0,Arrays.asList(brands).indexOf(brand))),d=spinner(new String[]{"全部交付方式","自有账号代充","共享／合租","卡密／兑换码","成品账号","镜像服务","报价比价"},Math.max(0,Arrays.asList(types).indexOf(delivery)));b.setContentDescription("筛选 AI 产品");d.setContentDescription("筛选交付方式");add(options,b,0);add(options,d,0);add(body,options,8);b.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){brand=brands[i];renderCards();}});d.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){delivery=types[i];renderCards();}});}
    private void renderCards(){if(cards==null)return;cards.removeAllViews();filters.removeAllViews();String[] keys=mode.equals("nodes")?new String[]{"all","proxy","airport","favorites"}:new String[]{"all","primary","alternatives","favorites"};String[] titles=mode.equals("nodes")?new String[]{"全部","代理 IP 5家","机场 5家","我的收藏"}:new String[]{"全部","主推荐 5个","备选 2个","我的收藏"};
        for(int i=0;i<keys.length;i++){final String key=keys[i];Button b=button(titles[i],filter.equals(key));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(42));lp.rightMargin=dp(7);filters.addView(b,lp);b.setOnClickListener(v->{filter=key;renderCards();});}
        Set<String> fav=favorites();int shown=0;JSONArray groups=data.optJSONArray("groups");for(int g=0;g<groups.length();g++){JSONObject group=groups.optJSONObject(g);if(!filter.equals("all")&&!filter.equals("favorites")&&!filter.equals(group.optString("id")))continue;JSONArray entries=group.optJSONArray("entries");boolean heading=false;for(int i=0;i<entries.length();i++){JSONObject e=entries.optJSONObject(i);if(filter.equals("favorites")&&!fav.contains(e.optString("id"))||!ServiceDirectory.matches(e,query,brand,delivery))continue;if(!heading){TextView h=text(group.optString("name",group.optString("title")),19,INK);h.setTypeface(null,Typeface.BOLD);add(cards,h,22);TextView sub=text(group.optString("subtitle"),11,MUTED);sub.setMaxLines(3);add(cards,sub,6);heading=true;}card(e,fav);shown++;}}
        JSONArray extras=data.optJSONArray("shortcuts");if(extras!=null&&(filter.equals("all")||filter.equals("favorites")))for(int i=0;i<extras.length();i++){JSONObject e=extras.optJSONObject(i);if(filter.equals("favorites")&&!fav.contains(e.optString("id"))||!ServiceDirectory.matches(e,query,"all","all"))continue;add(cards,text("额外入口 · 不计入 5＋5",18,INK),22);card(e,fav);shown++;}
        count.setText("显示 "+shown+" 个入口 · "+(mode.equals("nodes")?"节点与 AI 会员独立分组":"按最新截图顺序"));if(shown==0)add(cards,text("暂无匹配网站，试试更换筛选或搜索词。",14,MUTED),22);
    }
    private void card(JSONObject e,Set<String> fav){LinearLayout card=col();card.setPadding(dp(17),dp(17),dp(17),dp(17));card.setBackground(shape(0xffffffff,21));TextView name=text(e.optString("name"),18,INK);name.setTypeface(null,Typeface.BOLD);add(card,name,0);add(card,text(e.optString("role",e.optString("price",e.optString("label"))),12,GREEN),7);TextView description=text(e.optString("summary",e.optString("desc")),12,MUTED);description.setMaxLines(2);add(card,description,8);TextView payment=text(e.optString("payment",e.optString("verified")),11,MUTED);payment.setMaxLines(2);add(card,payment,8);
        LinearLayout actions=row();Button visit=button("访问原站",true),detail=button("详情",false),star=button(fav.contains(e.optString("id"))?"★":"☆",false);visit.setContentDescription("访问 "+e.optString("name"));detail.setContentDescription("详情 "+e.optString("name"));star.setContentDescription((fav.contains(e.optString("id"))?"取消收藏":"收藏")+e.optString("name"));visit.setOnClickListener(v->startActivity(new Intent(this,InAppBrowserActivity.class).putExtra("url",e.optString("url"))));detail.setOnClickListener(v->details(e));star.setOnClickListener(v->{Set<String> entries=favorites();String id=e.optString("id");if(!entries.add(id))entries.remove(id);if(prefs.edit().putStringSet(mode+":favorites",entries).commit())renderCards();else Toast.makeText(this,"收藏保存失败",Toast.LENGTH_SHORT).show();});actions.addView(visit,new LinearLayout.LayoutParams(0,dp(44),1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(62),dp(44));lp.leftMargin=dp(7);actions.addView(detail,lp);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(dp(48),dp(44));sp.leftMargin=dp(7);actions.addView(star,sp);add(card,actions,14);add(cards,card,12);
    }
    private void details(JSONObject e){StringBuilder value=new StringBuilder(e.optString("url"));for(String key:new String[]{"role","price","summary","desc","payment","tip","verified","source"}){String s=e.optString(key);if(!s.isBlank())value.append("\n\n").append(s);}TextView content=text(value.toString(),14,INK);content.setTextIsSelectable(true);content.setPadding(dp(22),dp(16),dp(22),dp(20));ScrollView scroll=new ScrollView(this);scroll.addView(content);new AlertDialog.Builder(this).setTitle(e.optString("name")).setView(scroll).setNegativeButton("关闭",null).setPositiveButton("访问原站",(d,w)->startActivity(new Intent(this,InAppBrowserActivity.class).putExtra("url",e.optString("url")))).show();}
    private void refresh(){if(refreshing)return;refreshing=true;refresh.setEnabled(false);status.setText("正在读取最新目录…");jobs.execute(()->{String message;JSONObject next=null;try{URL url=new URL("https://raw.githubusercontent.com/nmm26301-maker/zhi-geng/main/data/"+asset()+"?v="+System.currentTimeMillis());HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(8000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Cache-Control","no-cache");try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream()){next=ServiceDirectory.validate(mode,read(in));}}finally{c.disconnect();}message="最新目录已更新 · "+next.optString("updatedAt");}catch(Exception e){message="刷新未完成，保留已有名单 · "+e.getMessage();}JSONObject got=next;String note=message;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;refreshing=false;refresh.setEnabled(true);if(got!=null){data=got;prefs.edit().putString(mode+":data",data.toString()).apply();renderCards();}status.setText(note);});});}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("filter",filter);state.putString("query",query);state.putString("brand",brand);state.putString("delivery",delivery);}
    @Override protected void onDestroy(){jobs.shutdownNow();super.onDestroy();}
}
